  exists (4 * j + 8), (cden (Ip q0 ++ [S0]) [] j A1_1RB1LD_0LC1RD_1RB1LC_1LA0RB).
  split; [lia|]. split; [| exact (gei_1RB1LD_0LC1RD_1RB1LC_1LA0RB p j q0 E)].
  rewrite (gsi_1RB1LD_0LC1RD_1RB1LC_1LA0RB p j q0 E).
  exact (srun_sound tm false true chi_1RB1LD_0LC1RD_1RB1LC_1LA0RB A0_1RB1LD_0LC1RD_1RB1LC_1LA0RB A1_1RB1LD_0LC1RD_1RB1LC_1LA0RB 4 8
           run_int_1RB1LD_0LC1RD_1RB1LC_1LA0RB (Ip q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LD_0LC1RD_1RB1LC_1LA0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LD_0LC1RD_1RB1LC_1LA0RB.
