  assert (H : match csteps tm_1RB1LD_1LB1LC_1RD0LC_0RD1LA 14 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1LD_1LB1LC_1RD0LC_0RD1LA 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LD_1LB1LC_1RD0LC_0RD1LA : existsb (fun tg => cfires tm_1RB1LD_1LB1LC_1RD0LC_0RD1LA c0 14 tg) pins_1RB1LD_1LB1LC_1RD0LC_0RD1LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_1LB1LC_1RD0LC_0RD1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_1LB1LC_1RD0LC_0RD1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_1LB1LC_1RD0LC_0RD1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_1LB1LC_1RD0LC_0RD1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_1LB1LC_1RD0LC_0RD1LA : forall t, ~ In t pins_1RB1LD_1LB1LC_1RD0LC_0RD1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_1LB1LC_1RD0LC_0RD1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LD_1LB1LC_1RD0LC_0RD1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LD_1LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_1LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 3; SCycL 1 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LD_1LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_1LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 3; SCycL 1 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LD_1LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 3; SCycL 1 0; SWin 2; SCycR 1; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem qhtr_1RB1LD_1LB1LC_1RD0LC_0RD1LA : NonHalt tm_1RB1LD_1LB1LC_1RD0LC_0RD1LA /\ QHBoundTr 32779478 tm_1RB1LD_1LB1LC_1RD0LC_0RD1LA /\ QuasiHaltsTr tm_1RB1LD_1LB1LC_1RD0LC_0RD1LA.
Proof.
  apply (lap_qh_stage tm_1RB1LD_1LB1LC_1RD0LC_0RD1LA pins_1RB1LD_1LB1LC_1RD0LC_0RD1LA Cc 1 14 32779478).
  - exact bootq_1RB1LD_1LB1LC_1RD0LC_0RD1LA.
  - intros p _. apply lap_1RB1LD_1LB1LC_1RD0LC_0RD1LA.
  - intros t Ht p _. apply fire_1RB1LD_1LB1LC_1RD0LC_0RD1LA. exact Ht.
  - exact wit_1RB1LD_1LB1LC_1RD0LC_0RD1LA.
  - apply qcleb_QC_25. reflexivity.
Qed.

