Definition mk_1RB1LD_1LC0RB_0LC0RD_1LA1RD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1LD_1LC0RB_0LC0RD_1LA1RD.

(** 1RB1LD_1LC0RB_0LC0RD_1LA1RD *)
(** 1RB1LD_1LC0RB_0LC0RD_1LA1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LD_1LC0RB_0LC0RD_1LA1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StB
  | StC, S0 => mk S0 DL StC | StC, S1 => mk S0 DR StD
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S1 DR StD end.

(** Its mirror 1LB1RD_1RC0LB_0RC0LD_1RA1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StB
  | StC, S0 => mk S0 DR StC | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LD_1LC0RB_0LC0RD_1LA1RD : list Instr := [(StA, S1); (StD, S1)].
Definition tmw_1RB1LD_1LC0RB_0LC0RD_1LA1RD : TM := tm_wrap_trs tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD pins_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
Local Notation tm := tmw_1RB1LD_1LC0RB_0LC0RD_1LA1RD.

Lemma mirror_ok_1RB1LD_1LC0RB_0LC0RD_1LA1RD : mirror_tm tm_1RB1LD_1LC0RB_0LC0RD_1LA1RD = tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1LD_1LC0RB_0LC0RD_1LA1RD (p : positive) : cconf := (StD, (Kp p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1LD_1LC0RB_0LC0RD_1LA1RD.

(** ** The certificate *)

Definition A0_1RB1LD_1LC0RB_0LC0RD_1LA1RD : sconf := mkC StD (mkS [] [S1] 1 0 [S0]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1LD_1LC0RB_0LC0RD_1LA1RD : sconf := mkC StD (mkS [] [S0] 1 0 [S1]) S0 (mkS [S0] [] 0 0 []).
Definition chi_1RB1LD_1LC0RB_0LC0RD_1LA1RD : list lstep := [SWinR 2; SCycL 1 0; SWin 2; SCycR 1; SWin 2].

Lemma run_int_1RB1LD_1LC0RB_0LC0RD_1LA1RD : srun tm false true chi_1RB1LD_1LC0RB_0LC0RD_1LA1RD A0_1RB1LD_1LC0RB_0LC0RD_1LA1RD = Some (A1_1RB1LD_1LC0RB_0LC0RD_1LA1RD, 2, 6).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LD_1LC0RB_0LC0RD_1LA1RD : sconf := mkC StD (mkS [S1] [S1] 1 0 [S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LD_1LC0RB_0LC0RD_1LA1RD : sconf := mkC StD (mkS [] [S0] 1 1 [S1]) S0 (mkS [S0] [] 0 0 []).
Definition cho_1RB1LD_1LC0RB_0LC0RD_1LA1RD : list lstep := [SWinR 3; SCycL 1 0; SWin 2; SCycR 1; SWin 3; SFoldL 1].

Lemma run_ovf_1RB1LD_1LC0RB_0LC0RD_1LA1RD : srun tm true true cho_1RB1LD_1LC0RB_0LC0RD_1LA1RD B0_1RB1LD_1LC0RB_0LC0RD_1LA1RD = Some (B1_1RB1LD_1LC0RB_0LC0RD_1LA1RD, 2, 8).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j A0_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p j q0 E) as (H1 & _).
  unfold Cc_1RB1LD_1LC0RB_0LC0RD_1LA1RD, cden, A0_1RB1LD_1LC0RB_0LC0RD_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Kp q0 ++ [S0]) [] j A1_1RB1LD_1LC0RB_0LC0RD_1LA1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p j q0 E) as (_ & H2).
  unfold Cc_1RB1LD_1LC0RB_0LC0RD_1LA1RD, cden, A1_1RB1LD_1LC0RB_0LC0RD_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (2 * j + 6), (cden (Kp q0 ++ [S0]) [] j A1_1RB1LD_1LC0RB_0LC0RD_1LA1RD).
  split; [lia|]. split; [| exact (gei_1RB1LD_1LC0RB_0LC0RD_1LA1RD p j q0 E)].
  rewrite (gsi_1RB1LD_1LC0RB_0LC0RD_1LA1RD p j q0 E).
  exact (srun_sound tm false true chi_1RB1LD_1LC0RB_0LC0RD_1LA1RD A0_1RB1LD_1LC0RB_0LC0RD_1LA1RD A1_1RB1LD_1LC0RB_0LC0RD_1LA1RD 2 6
           run_int_1RB1LD_1LC0RB_0LC0RD_1LA1RD (Kp q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (H1 & _).
  unfold Cc_1RB1LD_1LC0RB_0LC0RD_1LA1RD, cden, B0_1RB1LD_1LC0RB_0LC0RD_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_1LC0RB_0LC0RD_1LA1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LD_1LC0RB_0LC0RD_1LA1RD
             = (StD, (rep [S0] (S j) ++ [S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1LD_1LC0RB_0LC0RD_1LA1RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LD_1LC0RB_0LC0RD_1LA1RD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1LD_1LC0RB_0LC0RD_1LA1RD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LD_1LC0RB_0LC0RD_1LA1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_1LC0RB_0LC0RD_1LA1RD B0_1RB1LD_1LC0RB_0LC0RD_1LA1RD B1_1RB1LD_1LC0RB_0LC0RD_1LA1RD 2 8 p j' [] []).
    + exact run_ovf_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_1LC0RB_0LC0RD_1LA1RD p j' E).
    + exact (geo_1RB1LD_1LC0RB_0LC0RD_1LA1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LD_1LC0RB_0LC0RD_1LA1RD : stepn tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD 6 InitES = Some (lift (Cc 3)).
Proof.
  assert (H : match csteps tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD 6 c0 with
              | Some c => ceqb c (Cc 3) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD 6 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LD_1LC0RB_0LC0RD_1LA1RD : existsb (fun tg => cfires tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD c0 6 tg) pins_1RB1LD_1LC0RB_0LC0RD_1LA1RD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_1LC0RB_0LC0RD_1LA1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_1LC0RB_0LC0RD_1LA1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_1LC0RB_0LC0RD_1LA1RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_1LC0RB_0LC0RD_1LA1RD : forall t, ~ In t pins_1RB1LD_1LC0RB_0LC0RD_1LA1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1LC0RB_0LC0RD_1LA1RD [SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1LC0RB_0LC0RD_1LA1RD [SWinR 3; SCycL 1 0; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1LC0RB_0LC0RD_1LA1RD [SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1LC0RB_0LC0RD_1LA1RD [SWinR 3; SCycL 1 0; SWin 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1LC0RB_0LC0RD_1LA1RD [SWinR 3; SCycL 1 0; SWin 2; SCycR 1; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1LC0RB_0LC0RD_1LA1RD [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_1RB1LD_1LC0RB_0LC0RD_1LA1RD : NonHalt tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD /\ QHBoundTr 32779478 tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD /\ QuasiHaltsTr tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
Proof.
  apply (lap_qh_stage tmm_1RB1LD_1LC0RB_0LC0RD_1LA1RD pins_1RB1LD_1LC0RB_0LC0RD_1LA1RD Cc 3 6 32779478).
  - exact bootq_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
  - intros p _. apply lap_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
  - intros t Ht p _. apply fire_1RB1LD_1LC0RB_0LC0RD_1LA1RD. exact Ht.
  - exact wit_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
  - apply qcleb_QC_25. reflexivity.
Qed.

Theorem qhtr_1RB1LD_1LC0RB_0LC0RD_1LA1RD : NonHalt tm_1RB1LD_1LC0RB_0LC0RD_1LA1RD /\ QHBoundTr 32779478 tm_1RB1LD_1LC0RB_0LC0RD_1LA1RD /\ QuasiHaltsTr tm_1RB1LD_1LC0RB_0LC0RD_1LA1RD.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB1LD_1LC0RB_0LC0RD_1LA1RD). rewrite mirror_ok_1RB1LD_1LC0RB_0LC0RD_1LA1RD. exact qhtrm_1RB1LD_1LC0RB_0LC0RD_1LA1RD. Qed.

End B_QC_25_030.

