Definition Z0_1RB1LD_1LC0RB_0LD1RA_0LD1RB : sconf := mkC StB (mkS [S0] [] 0 0 []) S0 (mkS [S1] [] 0 0 []).
Definition Z1_1RB1LD_1LC0RB_0LD1RA_0LD1RB : sconf := mkC StB (mkS [S1] [] 0 0 []) S0 (mkS [S1] [] 0 0 []).
Definition chz_1RB1LD_1LC0RB_0LD1RA_0LD1RB : list lstep := [SWin 8].

Lemma run_z_1RB1LD_1LC0RB_0LD1RA_0LD1RB : srun tm false true chz_1RB1LD_1LC0RB_0LD1RA_0LD1RB Z0_1RB1LD_1LC0RB_0LD1RA_0LD1RB = Some (Z1_1RB1LD_1LC0RB_0LD1RA_0LD1RB, 0, 8).
Proof. vm_compute. reflexivity. Qed.

