Lemma lapi_1RB1LD_1LC0RB_0LD1RA_0LD1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LD_1LC0RB_0LD1RA_0LD1RB p q0 E) as (HA & HB).
    exists (0 * 0 + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LD_1LC0RB_0LD1RA_0LD1RB Z0_1RB1LD_1LC0RB_0LD1RA_0LD1RB Z1_1RB1LD_1LC0RB_0LD1RA_0LD1RB 0 8
               run_z_1RB1LD_1LC0RB_0LD1RA_0LD1RB (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LD_1LC0RB_0LD1RA_0LD1RB p j' q0 E) as (HA & HB).
    exists (2 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LD_1LC0RB_0LD1RA_0LD1RB P0_1RB1LD_1LC0RB_0LD1RA_0LD1RB P1_1RB1LD_1LC0RB_0LD1RA_0LD1RB 2 10
               run_p_1RB1LD_1LC0RB_0LD1RA_0LD1RB (Kp q0 ++ [S0]) [] j'
