(** ** The lap *)

Lemma lap_1RB1LD_1LC0RD_1RA1LB_0LC1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LD_1LC0RD_1RA1LB_0LC1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_1LC0RD_1RA1LB_0LC1RD B0_1RB1LD_1LC0RD_1RA1LB_0LC1RD B1_1RB1LD_1LC0RD_1RA1LB_0LC1RD 4 8 p j' [] []).
    + exact run_ovf_1RB1LD_1LC0RD_1RA1LB_0LC1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_1LC0RD_1RA1LB_0LC1RD p j' E).
    + exact (geo_1RB1LD_1LC0RD_1RA1LB_0LC1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LD_1LC0RD_1RA1LB_0LC1RD : stepn tm_1RB1LD_1LC0RD_1RA1LB_0LC1RD 22 InitES = Some (lift (Cc 2)).
Proof.
