(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LD_1LC0RD_1RA1LB_0LC1RD : existsb (fun tg => cfires tm_1RB1LD_1LC0RD_1RA1LB_0LC1RD c0 22 tg) pins_1RB1LD_1LC0RD_1RA1LB_0LC1RD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_1LC0RD_1RA1LB_0LC1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_1LC0RD_1RA1LB_0LC1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_1LC0RD_1RA1LB_0LC1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_1LC0RD_1RA1LB_0LC1RD p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1LD_1LC0RD_1RA1LB_0LC1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LD_1LC0RD_1RA1LB_0LC1RD = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB1LD_1LC0RD_1RA1LB_0LC1RD p j (Jp q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LD_1LC0RD_1RA1LB_0LC1RD p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_1LC0RD_1RA1LB_0LC1RD : forall t, ~ In t pins_1RB1LD_1LC0RD_1RA1LB_0LC1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_1LC0RD_1RA1LB_0LC1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LD_1LC0RD_1RA1LB_0LC1RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LD_1LC0RD_1RA1LB_0LC1RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LD_1LC0RD_1RA1LB_0LC1RD (StB, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LD_1LC0RD_1RA1LB_0LC1RD [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_1LC0RD_1RA1LB_0LC1RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LD_1LC0RD_1RA1LB_0LC1RD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_1LC0RD_1RA1LB_0LC1RD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LD_1LC0RD_1RA1LB_0LC1RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
Qed.

Theorem qhtr_1RB1LD_1LC0RD_1RA1LB_0LC1RD : NonHalt tm_1RB1LD_1LC0RD_1RA1LB_0LC1RD /\ QHBoundTr 32779478 tm_1RB1LD_1LC0RD_1RA1LB_0LC1RD /\ QuasiHaltsTr tm_1RB1LD_1LC0RD_1RA1LB_0LC1RD.
Proof.
  apply (lap_qh_stage tm_1RB1LD_1LC0RD_1RA1LB_0LC1RD pins_1RB1LD_1LC0RD_1RA1LB_0LC1RD Cc 2 22 32779478).
  - exact bootq_1RB1LD_1LC0RD_1RA1LB_0LC1RD.
  - intros p _. apply lap_1RB1LD_1LC0RD_1RA1LB_0LC1RD.
  - intros t Ht p _. apply fire_1RB1LD_1LC0RD_1RA1LB_0LC1RD. exact Ht.
  - exact wit_1RB1LD_1LC0RD_1RA1LB_0LC1RD.
  - apply qcleb_QC_25. reflexivity.
Qed.

